// does not exist, where nobody could find or drop it.
var mixedMethods = suite.NewNameSet("Mixed", mixedStore, mixedGet)

// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c MixedCheck) bind(
	fx MixedFixture,
) (suite.Check[Mixed], error) {
	out := suite.Check[Mixed]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error
	bodies := 0
	if c.Run != nil {
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, mixedMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s Mixed) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub MixedSubject) {
			rw(tb, sub, fx)
		}
	}
	if err := suite.OneBody(c.Name, bodies, "Run, RunWith"); err != nil {
		return out, err
	}
	if c.Method != "" && c.Run == nil {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunMixed runs every check — the generated ones and any you
// wrote — against every implementation you pass it.
//
// Each argument describes one thing to do, in any order: an
// implementation to test, a table of your own checks, sample inputs to
// use, or checks to leave out.
//
//	RunMixed(t,
//		MixedHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		MixedSuite.Without(MixedSuite.Checks.Store.Smoke()),
//	)
//
// Pass two implementations to compare them against each other, and mark
// the one you trust as the Oracle. Every check runs as its own subtest
// named after the implementation and the check, so `go test -run` can
// select one.
//
// A check that needs something your implementation has not supplied
// fails rather than skipping, and says which field to fill in. That is
// deliberate: a skipped check is how a claim goes unchecked while the
// run stays green.
func RunMixed(
	t *testing.T, opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Checked here, after reading every argument and before running
	// anything: a misconfigured run reports all of its problems at once
	// rather than one per attempt.
	rc.Fail(t, "RunMixed")
	suite.Run(t,
		mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveMixed runs each of your checks against the deliberately
// broken implementation it names, and fails if the check does not catch
// it.
//
//	func TestMyChecksCanFail(t *testing.T) { ProveMixed(t, myChecks) }
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
func ProveMixed(
	t *testing.T, checks MixedChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := mixedNewFixture()
	bound := make([]suite.Check[Mixed], 0, len(checks))
	defects := prove.Defects[Mixed]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveMixed: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveMixed: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Mixed]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

// mixedModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func mixedModelRows(fx MixedFixture) []suite.Check[Mixed] {
	return []suite.Check[Mixed]{
		{
			ID:          mixedCheckIndex.Model.Laws(),
			Class:       suite.ClassLaws,
			Claim:       "every bound law holds over random operation sequences",
			Falsifiable: suite.Argued("no defect is planted for it: the proofs beside this file break one method at a time, and a claim about sequences needs a subject that is wrong over a history"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertLaws(tb, sub, fx)
			},
		},
		{
			ID:          mixedCheckIndex.Model.Agrees(),
			Class:       suite.ClassDifferential,
			Claim:       "every operation sequence leaves the subject agreeing with the reference",
			Falsifiable: suite.Argued("no defect is planted for it: the proofs beside this file break one method at a time, and a claim about sequences needs a subject that is wrong over a history"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertAgrees(tb, sub, fx)
			},
		},
	}
}

// --- Mixed's model tier -------------------------------------------
//
// Random sequences of Mixed's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and MixedSuite.Without declines any of them by name.
//
//	Reference: derived — a resolution-pinning map over the Value fixture pair,
//	           keyed on Key; NewMixedModelReference replaces it
//	Sequences: Store (writer), Get (reader)
//	Values:    the fixture pair blended with arbitrary draws, each keyed
//	           from the pool
//	Laws:      AUTO-STICKY
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — the sticky claim negates it — a write to a resolved key must not change what a read answers

// mixedModelKeys is the key pool every key slot draws from.
//
// Two keys, and deliberately not more: collision density is what makes a
// read revisit a write and an overwrite land on held state. A wide key
// pool would pass every comparison over a history that never collides.
func mixedModelKeys(fx MixedFixture) *model.Generator[string] {
	return model.SampledFrom([]string{fx.Key(), fx.KeyOther()})
}

// mixedModelValues is the value pool every value slot draws from.
//
// The fixture pair blended with arbitrary draws: the pair keeps identical
// rewrites frequent, the wide arm reaches values no fixture spells, and
// nothing in the claims licenses refusing either.
func mixedModelValues(fx MixedFixture) *model.Generator[sticky.Value] {
	keys := mixedModelKeys(fx)
	bodies := model.OneOf(
		model.SampledFrom([]sticky.Value{fx.Value(), fx.ValueOther()}),
		model.Make[sticky.Value](),
	)
	// Every drawn value lands on a pooled key: a key rewritten under
	// another body is the history latest-write-wins is about, and a
	// fresh-keyed value would never collide with one already held.
	return model.Custom(func(t *model.T) sticky.Value {
		v := bodies.Draw(t, "value_body")
		v.Key = keys.Draw(t, "value_key")
		return v
	})
}

// mixedModelMiss is what the reference reports for a key nothing
// wrote. Only its presence is compared — a subject reports its own miss
// sentinel, and the run asks whether both sides missed, not how they spelled
// it. Where the declaration stamps a sentinel of its own, the oracle takes
// that identity instead and this var is not declared.
var mixedModelMiss = errors.New("mixed: the model reference holds nothing under the key")

// mixedModelKeyOf projects a value's identity — the one derivation the
// reference keys on and every keyed law reuses, so the two cannot disagree
// about which field is the key.
func mixedModelKeyOf(v sticky.Value) string {
	return v.Key
}

// mixedModelReference adapts the shipped StickyStore oracle to Mixed.
// Deliberately simple: its correctness is read, not tested.
type mixedModelReference struct {
	store *ref.StickyStore[string, sticky.Value]
}

// NewMixedModelReference builds one. Exported because a consumer whose
// semantics outrun their shape replaces it, and because the proof beside
// this file drives it as a subject of its own.
func NewMixedModelReference() Mixed {
	return &mixedModelReference{store: ref.NewStickyStore[string, sticky.Value](
		mixedModelKeyOf,
		mixedModelMiss,
	)}
}

func (r *mixedModelReference) Store(ctx context.Context, v sticky.Value) error {
	return r.store.Put(ctx, v)
}

func (r *mixedModelReference) Get(ctx context.Context, key string) (sticky.Value, error) {
	return r.store.Get(ctx, key)
}

// mixedModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func mixedModelActions(fx MixedFixture) []model.Action[Mixed] {
	keys := mixedModelKeys(fx)
	values := mixedModelValues(fx)
	return []model.Action[Mixed]{
		action.Writer("Store", values,
			func(ctx context.Context, s sticky.Mixed, v sticky.Value) error {
				return s.Store(ctx, v)
			}),
		action.Reader("Get", keys,
			func(ctx context.Context, s sticky.Mixed, k string) (sticky.Value, error) {
				return s.Get(ctx, k)
			}),
	}
}

// mixedModelLaws is the laws the classifications earned and this build
// could fill.
//
// Observational, every one of them: a law never mutates, so running them
// inside the sequences is safe for every step that follows. What they
// judge is the subject's own behaviour, which is why they are a separate
// leg from the reference comparison rather than more oracles on it.
func mixedModelLaws(fx MixedFixture) []law.Law[Mixed] {
	keys := mixedModelKeys(fx)
	return []law.Law[Mixed]{
		&law.Sticky[sticky.Mixed, string, sticky.Value]{
			Read: func(rt *model.T, s sticky.Mixed, k string) (sticky.Value, error) {
				return s.Get(rt.Context(), k)
			},
			Keys: keys,
		},
	}
}

// mixedAssertLaws drives the same sequences with the bound laws as the only
// oracle, and reports when they engaged nothing.
//
// The differential verdict is off here, and that is the whole reason this
// is a second leg rather than more options on the first: with it armed, a
// subject broken anywhere disagrees at step 0 and no law is ever reached,
// which makes "can this law catch a defect" unanswerable.
//
// The report is the other half. A law behind a precondition the subject
// refuses on every draw passes every time and asserts nothing, and from
// outside that is indistinguishable from a law that held.
func mixedAssertLaws(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()

	// The run's declared oracle where one exists, the derived reference
	// otherwise — and the report says which, because a law held against a
	// second copy of the subject is a weaker claim than the same law held
	// against something written independently.
	buildRef, tier := legs.Reference(tb, sub, NewMixedModelReference)
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Mixed { return sub.New(tb) }, buildRef,
		mixedModelActions(fx),
		mixedModelLaws(fx))
}

// mixedAssertAgrees drives random operation sequences against the subject and
// the reference, comparing after every call.
//
// The differential is the strongest oracle this tier has, and it is this
// leg's whole job: no laws are registered, so nothing competes with it and
// a disagreement is what ends the run.
func mixedAssertAgrees(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()
	legs.Differential(tb, sub,
		NewMixedModelReference,
		mixedModelActions(fx))
}

